function p(c,r,i=1.5){const n=new Map;for(let e=0;e<c.length;e++){const t=c[e].subjectIdHash,a=1/(60+e+1);n.has(t)||n.set(t,{subjectIdHash:c[e].subjectIdHash,rrfScore:0,provenanceScore:1,finalScore:0,embeddingRank:null,treeRank:null,source:"embedding"});const o=n.get(t);o.rrfScore+=a,o.embeddingRank=e+1}for(let e=0;e<r.length;e++){const t=r[e].subjectIdHash,a=1/(60+e+1)*i;n.has(t)||n.set(t,{subjectIdHash:r[e].subjectIdHash,rrfScore:0,provenanceScore:1,finalScore:0,embeddingRank:null,treeRank:null,source:"tree"});const o=n.get(t);o.rrfScore+=a,o.treeRank=e+1,o.embeddingRank!==null&&(o.source="both")}for(const e of n.values())e.finalScore=e.rrfScore;const s=Array.from(n.values()).sort((e,t)=>t.rrfScore-e.rrfScore);let d=0;const f=new Set(c.map(e=>e.subjectIdHash)),l=new Set(r.map(e=>e.subjectIdHash));for(const e of f)l.has(e)&&d++;return{results:s,stats:{embeddingCount:c.length,treeCount:r.length,overlapCount:d,totalUnique:n.size}}}function I(c,r,i,n=30){const s=new Map,d=Date.now(),f=n*24*60*60*1e3;for(const l of c){const e=l.subjectIdHash,t=r.get(l.subjectIdHash);let a=1;if(t?.lastMentioned){const u=d-t.lastMentioned.getTime();a=Math.exp(-.693*u/f)}let o=t?.assemblyConfidence??1,h=1;if(i?.assemblySteps){const u=i.assemblySteps.filter(S=>S.targetId===e);if(u.length>0){let S=0;for(const g of u)S+=g.evidence?.length||0;h=1+Math.log1p(S)}}const b=a*o*h;s.set(e,{recencyDecay:a,confidence:o,evidenceWeight:h,combined:b})}return s}function E(c,r){return c.map(n=>{const s=n.subjectIdHash,f=r.get(s)?.combined??1;return{...n,provenanceScore:f,finalScore:n.rrfScore*f}}).sort((n,s)=>s.finalScore-n.finalScore)}export{I as computeProvenance,p as mergeResults,E as reRankByProvenance};
